EXPECTED="d1deeb3b0cb65fd52563355cd5497a2319ddd7bc9fe4aaeaca91449f155c998c"
def load():
    x=json.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
    h=x.pop('canonical_sha256')
    got=hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    x['canonical_sha256']=h
    if h!=EXPECTED or got!=EXPECTED:
        raise SystemExit('retained Picard base bundle hash regression')
    if x['upstream_git_blob_sha1']!='0422b69847f2afb97cb7b3ed02ebef91279f61b1':
        raise SystemExit('retained Picard upstream lock moved')
    if len(x['picard_gram_64x64'])!=64 or any(len(r)!=64 for r in x['picard_gram_64x64']):
        raise SystemExit('retained Picard Gram shape regression')
    return x
